"""Lesson revisions drawn from the recorded review sessions (Mark Mattson, 2022), written in this site's own words from notes
taken on the full session transcripts. Adds key ideas and common mistakes to the lessons. Run after author_deep.py."""
import json, os
from author_common import ROOT
R = {}
def rev(sub, ideas=(), pitfalls=()): R.setdefault(sub, {'ideas': [], 'pitfalls': []}); R[sub]['ideas'] += list(ideas); R[sub]['pitfalls'] += list(pitfalls)
# ---------------- Statics ----------------
rev('statics-a', [('Slope triangles instead of angles', "When a direction is given as a slope, such as 3 vertical in 4 horizontal, the components are the force times the side ratios of that triangle: 3/5 and 4/5 of the force. No angle has to be found.")],
    ["Answering with one component when the question asks for the resultant, or the other way round."])
rev('statics-b', [('Distributed loads as single forces', "A uniform load w over a length L acts as w L at mid-length. A triangular load acts as half its peak intensity times its length, one third of the length from the tall end. Split a trapezoidal load into a rectangle and a triangle."),
    ('Locating the equivalent force', "The single force that replaces a set of loads sits where it gives the same moment: distance = sum of moments / sum of forces. A centroid is the same calculation with areas in place of forces.")],
    ["Placing the resultant of a triangular load at mid-length."])
rev('statics-c', [('Where to take moments', "Take moments about the point that the most unknown forces pass through. Each of them drops out, and one equation often gives the answer directly.")],
    ["Sign slips when moving moment terms across the equals sign. Re-check the sense of each term.", "Using a mass in kilograms as a force. Multiply by 9.81 for newtons and divide by 1,000 for kilonewtons."])
rev('statics-d', [('Force triangles match geometry triangles', "A cable or truss member carries force only along its own line, so the components of its force are in the same ratio as the member's rise, run and length. Use those ratios instead of solving for the angle."),
    ('Assume tension', "Draw every unknown member force pulling away from the joint. A positive answer is then tension and a negative one compression, with no guessing.")],
    ["Forgetting that a diagonal member carries horizontal force at a joint as well as vertical."])
rev('statics-f', [('Parts that share the axis add directly', "When the parts of a section have their centroids on the axis in question, their moments of inertia add or subtract with no parallel-axis term; a channel about its mid-height is a large rectangle minus a smaller one. The A d^{2} term appears only for parts offset from the axis, and it often dominates.")])
rev('statics-g', [('Each sliding surface has its own normal force', "With stacked blocks, friction acts on every face that slides. The upper face carries the weight above it; the lower face carries both blocks. Find each normal force separately."),
    ('A horizontal push on an incline', "A horizontal force on a block on a slope has a component into the surface, so it raises the normal force and with it the friction. Put the axes along and across the slope and solve the two equilibrium equations together.")])
# ---------------- Mathematics ----------------
rev('math-a', [('Slope as a step', "A slope of m means y changes by m for each unit step in x. Walking from a known point in those steps is a quick way to test whether another point lies on the line."),
    ('The circle equation is the distance formula', "(x - h)^{2} + (y - k)^{2} = r^{2} says every point on the circle is a distance r from the centre. Given the centre and one point, the radius is the distance between them.")],
    ["Reading the centre's signs backwards: (x - 3)^{2} puts the centre at x = +3."])
rev('math-b', [('A tangent with a given slope', "To find where a curve has a particular slope, set the derivative equal to that slope and solve. Finding a maximum or minimum is the special case where the slope is zero."),
    ('Read the derivative table backwards', "Integration undoes differentiation, so the derivative table doubles as an integral table: since the derivative of tan x is sec^{2} x, the integral of sec^{2} x is tan x."),
    ('Area between two curves', "Set the two functions equal to find where they cross; those are the limits. Then integrate the upper function minus the lower one.")])
rev('math-c', [('Two zero tests', "A dot product of zero means the vectors are perpendicular. A cross product of zero means they are parallel.")],
    ["Giving the sum of two vectors when a unit vector is asked for. Divide by the magnitude."])
rev('math-d', [('Spotting a binomial problem', "Repeated independent trials, each with the same two outcomes and the same probability, are binomial even when the word never appears. For 'at least k', take 1 minus the probability of at most k - 1."),
    ('What z measures', "z is the number of standard deviations between a value and the mean. A concrete mix is designed with its mean strength above the specified strength so that only a small tail of tests falls below it.")])
# ---------------- Structural ----------------
rev('structural-a', [('Slide a force along its line of action', "A force gives the same moment wherever it is placed along its own line. Move it to the point where one of its components passes through the moment centre, and that component drops out."),
    ('Sections through a truss', "With parallel chords, summing vertical forces on the cut piece gives the diagonal directly. With sloping chords, take moments about the point where the other two cut members meet."),
    ('Split a frame at its internal pins', "Pin forces show up only when the members are separated. They are equal and opposite on the two pieces, so solve the simpler piece first and carry its pin force, reversed, to the other.")],
    ["Stopping at a force component when the member force is asked for."])
rev('structural-b', [('Unit load method for a truss', "A truss joint's displacement is the sum over the members of f F L / (A E), where F is the member force under the real loads and f is its force under a unit load at the joint in the direction wanted. Zero-force members drop out of the sum.")],
    ["Using a beam table case that matches the loading but not the supports, or misreading how the table defines L.", "Mixing feet and inches in w L^{4} / (E I). With w in kips per foot and L in feet, the result needs a factor of 12^{3} to come out in inches."])
rev('structural-c', [('One load, two ways to buckle', "The same axial load could buckle the column about either axis, each with its own effective length and moment of inertia. Compute both critical loads; the smaller governs. Bracing the weak axis at mid-height quarters its slenderness effect, so the strong axis can end up governing.")],
    ["Checking only the weak axis when the two axes have different unbraced lengths."])
rev('structural-d', [('Stability of a gravity dam', "A gravity dam is checked as a rigid block on a unit length. Against sliding, compare the friction available, coefficient times weight, with the water thrust, half the unit weight of water times depth squared. Against overturning, compare the moment of the weight about the toe with the moment of the water thrust, which acts at one third of the depth.")])
rev('structural-e', [('The redundant as a correcting force', "Remove the extra support and let the beam deflect there under the load. The redundant reaction is the force that pushes that point back to zero deflection. With constant E I the stiffness cancels out of the result.")],
    ["Sharing load to supports by tributary length on a continuous beam. On two equal spans under uniform load the middle support carries 1.25 w L, not w L."])
rev('structural-f', [('Tributary area is a watershed', "A beam collects the floor load from halfway out to the neighbouring beam on each side, as a river collects rain from its watershed. Multiply the area load by that width to get the line load."),
    ('Live load reduction', "A large floor area is unlikely to carry its full live load everywhere at once, so the code allows the live load on members with a large tributary area to be reduced before the load combinations are applied. The handbook gives the formula and its limits.")],
    ["Skipping the live load reduction when the tributary area is large enough for it to apply."])
rev('structural-g', [('Two ways a tension member fails', "Yielding is checked on the gross area away from the holes, with a resistance factor of 0.90. Rupture is checked on the effective net area through the holes, with 0.75. Compare the two after applying the factors; the smaller governs. The hole deduction is the hole diameter plus 1/16 in for damage."),
    ('Columns with different lengths about each axis', "Compare K L / r for each axis and use the larger. The design tables are built on the weak axis, so a strong-axis length is converted to its weak-axis equivalent by dividing by r_{x} / r_{y}."),
    ('Beam strength falls with unbraced length', "A fully braced compact beam reaches its plastic moment. As the unbraced length grows past a first limit, the compression flange starts to buckle sideways and strength drops in a straight line; past a second limit the buckling is elastic and strength falls faster. A moment gradient factor raises the curve but never above the plastic moment.")])
rev('structural-h', [('Why beams are under-reinforced', "With a modest amount of steel the bars yield before the concrete crushes, so the beam sags and cracks visibly before it fails. With too much steel the concrete crushes first, without warning, and the code penalises that with a lower strength reduction factor."),
    ('Stirrups', "Shear strength is the concrete's contribution plus the stirrups' contribution, A_{v} f_{y} d / s, where A_{v} counts both legs of the stirrup. Stirrups are needed once the factored shear exceeds half the reduced concrete strength, and their spacing is capped at d / 2 so that a diagonal crack cannot pass between them."),
    ('Design strength of a tied column', "For a short tied column, the design axial strength is 0.80 × 0.65 × (0.85 f'_{c} (A_{g} - A_{st}) + f_{y} A_{st}). The 0.65 is the reduction factor for compression and the 0.80 allows for accidental eccentricity.")],
    ["Leaving the moment in kip-inches, or forgetting the strength reduction factor, when the question asks for design strength in kip-feet."])
