# ---------------- Geotechnical ----------------
rev('geotech-a', [('Dual symbols', "A coarse-grained soil with 5% to 12% fines gets a dual symbol, such as SW-SM, that reports both its grading and the plasticity of its fines."),
    ('Well graded or uniform', "A well-graded soil has many sizes, so small grains fill the gaps between large ones and its gradation curve is long and smooth. A uniform soil is mostly one size, like beach sand, and its curve is steep. The No. 200 sieve, 0.075 mm, separates sand from fines.")],
    ["Taking the plastic limit for the plasticity index. PI is the liquid limit minus the plastic limit."])
rev('geotech-b', [('Start with the phase diagram', "Sketch the three phases and fill in what is known, as you would a free-body diagram. Subtract to find the rest, and only then choose a formula. In a saturated soil there is no air, so the volume of voids equals the volume of water."),
    ('Density of water', "The handbook gives the unit weight of water. For mass-based problems use 1 g/cm^{3} = 1,000 kg/m^{3}.")])
rev('geotech-c', [('The compaction curve', "Too dry, and the grains lack the lubrication to pack together. Too wet, and water occupies space the grains could have filled. The peak between is the maximum dry density at the optimum water content, and more compactive effort moves the peak up and toward drier conditions."),
    ('Relative density is not relative compaction', "Relative compaction is field dry density over the laboratory maximum and is what specifications state. Relative density places a granular soil between its loosest and densest states. Field density is measured with a sand cone or a nuclear gauge.")])
