def main():
    n = 0
    for f in sorted(os.listdir(os.path.join(ROOT, 'guide'))):
        path = os.path.join(ROOT, 'guide', f); g = json.load(open(path))
        for s in g['sections']:
            r = R.get(s.get('subtopic'))
            if not r: continue
            s['ideas'] = [{'title': a, 'text': b} for a, b in r['ideas']] + s.get('ideas', [])
            s['pitfalls'] = s.get('pitfalls', []) + [p for p in r['pitfalls'] if p not in s.get('pitfalls', [])]
            s['credit'] = "Some of the points in this lesson follow Mark Mattson's 2022 FE review session for this topic, restated in this site's words."; n += 1
        json.dump(g, open(path, 'w'), indent=1, ensure_ascii=False); open(path, 'a').write('\n')
    print('lessons revised from the sessions:', n)
if __name__ == '__main__': main()
